INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-6', 'Do you offer annual SLA retainers?', 'هل تتوفر عقود صيانة وتشغيل سنوية؟', 'Contact Bait Al-Khair at impact@baitalkhair.org.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر impact@baitalkhair.org.bh أو إرسال طلب إلكتروني وسيرد فريق بيت الخير خلال يوم عمل واحد.', 'general', true, 6, now()) ON CONFLICT (id) DO NOTHING;
